import React, { useEffect, useState } from "react";
import { useLocation, useParams } from "react-router-dom";
import { Divider } from "@heroui/react";

import transportApi from "../../../api/transport/transportApi";
import useApi from "../../../hooks/useApi";
import { Avatar, Button, List } from "antd";

function VehicleDetails() {
  const location = useLocation();
  const [vehicle, setVehicle] = useState();

  const [item, setitem] = useState(
    location.state.item ? location.state.item : null
  );
  // console.log('category_id', category)

  const transportActionsApi = useApi(transportApi.transportAction);

  const getVehicle = async () => {
    await transportActionsApi.request({
      action: "SearchVehicleByRegistration",
      registration: item.registration,
    });
  };

  useEffect(() => {
    getVehicle();
  }, []);

  useEffect(() => {
    if (transportActionsApi.data && transportActionsApi.data.vehicle) {
      setVehicle(transportActionsApi.data.vehicle);
    }

    console.log("transportActionsApi.data", transportActionsApi.data);
  }, [transportActionsApi.data]);

  return (
    <div className="w-full mt-10 sm:mt-0">
      <div className="space-y-1">
        <h4 className="text-2xl font-bold ">{item ? item.registration : ""}</h4>
        <p className="text-small text-default-400">
          {item && item.route_title
            ? item.route_title
            : "No route details availabe"}
        </p>
      </div>
      <Divider className="my-4" />
      <div className="grid grid-cols-1 md:grid-cols-3 w-full">
        <div>
          <div>Routes</div>
          <div>
            {vehicle && vehicle.routes && vehicle.routes.length ? (
              <List
                itemLayout="horizontal"
                dataSource={vehicle.routes}
                renderItem={(item, index) => (
                  <List.Item>
                    <List.Item.Meta
                      avatar={<Avatar icon="truck" />}
                      title={<a href="https://ant.design">{item.title}</a>}
                      description={item.description}
                    />
                  </List.Item>
                )}
              />
            ) : (
              <p>No routes</p>
            )}
          </div>
        </div>
        <div className="shadow-md p-4 m-2">
          <div>
            <div>Crew Members</div>
            <div>
              {vehicle &&
              vehicle.crew_members &&
              vehicle.crew_members.length ? (
                <List
                  itemLayout="horizontal"
                  dataSource={vehicle.crew_members}
                  renderItem={(item, index) => (
                    <List.Item>
                      <List.Item.Meta
                        avatar={<Avatar icon="user" />}
                        title={
                          <a href="https://ant.design">
                            {item.first_name} {item.last_name}
                          </a>
                        }
                        description={item.personnel_type}
                      />
                    </List.Item>
                  )}
                />
              ) : (
                <p>No crew members</p>
              )}
            </div>
          </div>
        </div>
        <div>
          <div>Subscriptions</div>
          <div>
            {vehicle &&
            vehicle.sacco_subscriptions &&
            vehicle.sacco_subscriptions.length ? (
              <List
                itemLayout="horizontal"
                dataSource={vehicle.sacco_subscriptions}
                renderItem={(item, index) => (
                  <List.Item
                    actions={[
                      <Button type="primary" size="sm">
                        Subscribe
                      </Button>,
                      <Button type="primary" size="sm">
                        Opt Out
                      </Button>,
                    ]}
                  >
                    <List.Item.Meta
                      avatar={
                        <Avatar
                          src={`https://api.dicebear.com/7.x/miniavs/svg?seed=${index}`}
                        />
                      }
                      title={<a href="https://ant.design">{item.title}</a>}
                      description={
                        item.is_subscribed === "true" ? (
                          <p className="text-green-400 uppercase font-bold">
                            SUBSCRIBED
                          </p>
                        ) : (
                          <p className="text-red-400 uppercase font-bold">
                            NOT SUBSCRIBED
                          </p>
                        )
                      }
                    />
                  </List.Item>
                )}
              />
            ) : (
              <p>No subscriptions</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default VehicleDetails;
